from ortools.linear_solver import pywraplp
import json

def solve_packing_problem():
    W = 30
    H = 20

    T = 8
    L = [8, 7, 6, 5, 9, 4, 10, 3]
    W_i = [6, 5, 4, 5, 3, 7, 4, 8]
    V = [48, 35, 24, 25, 27, 28, 40, 24]
    Q = [2, 2, 2, 2, 2, 1, 1, 1]

    solver = pywraplp.Solver.CreateSolver("SCIP")
    INF = solver.infinity()

    N = Q.copy()
    total_instances = sum(N)

    x = {}
    y = {}
    r = {}
    a = {}
    l = {}
    h = {}

    M = max(max(L), max(W_i)) + max(W, H)

    for i in range(T):
        for k in range(N[i]):
            x[(i, k)] = solver.NumVar(0, W, f"x_{i}_{k}")
            y[(i, k)] = solver.NumVar(0, H, f"y_{i}_{k}")

            r[(i, k)] = solver.BoolVar(f"r_{i}_{k}")

            a[(i, k)] = solver.BoolVar(f"a_{i}_{k}")

            l[(i, k)] = solver.NumVar(0, M, f"l_{i}_{k}")
            h[(i, k)] = solver.NumVar(0, M, f"h_{i}_{k}")

    for i in range(T):
        for k in range(N[i]):
            solver.Add(l[(i, k)] == (1 - r[(i, k)]) * L[i] + r[(i, k)] * W_i[i])

            solver.Add(h[(i, k)] == (1 - r[(i, k)]) * W_i[i] + r[(i, k)] * L[i])

    for i in range(T):
        for k in range(N[i]):
            solver.Add(x[(i, k)] + l[(i, k)] <= W + M * (1 - a[(i, k)]))

            solver.Add(y[(i, k)] + h[(i, k)] <= H + M * (1 - a[(i, k)]))

            solver.Add(x[(i, k)] <= M * a[(i, k)])
            solver.Add(y[(i, k)] <= M * a[(i, k)])

    instances = []
    for i in range(T):
        for k in range(N[i]):
            instances.append((i, k))

    for idx1 in range(len(instances)):
        for idx2 in range(idx1 + 1, len(instances)):
            i1, k1 = instances[idx1]
            i2, k2 = instances[idx2]

            b1 = solver.BoolVar(f"b1_{i1}_{k1}_{i2}_{k2}")
            b2 = solver.BoolVar(f"b2_{i1}_{k1}_{i2}_{k2}")
            b3 = solver.BoolVar(f"b3_{i1}_{k1}_{i2}_{k2}")
            b4 = solver.BoolVar(f"b4_{i1}_{k1}_{i2}_{k2}")

            solver.Add(x[(i1, k1)] + l[(i1, k1)] <= x[(i2, k2)] + M * (1 - b1))

            solver.Add(x[(i2, k2)] + l[(i2, k2)] <= x[(i1, k1)] + M * (1 - b2))

            solver.Add(y[(i1, k1)] + h[(i1, k1)] <= y[(i2, k2)] + M * (1 - b3))

            solver.Add(y[(i2, k2)] + h[(i2, k2)] <= y[(i1, k1)] + M * (1 - b4))

            solver.Add(b1 + b2 + b3 + b4 >= a[(i1, k1)] + a[(i2, k2)] - 1)

    for i in range(T):
        solver.Add(sum(a[(i, k)] for k in range(N[i])) <= Q[i])

    objective = solver.Objective()
    for i in range(T):
        for k in range(N[i]):
            objective.SetCoefficient(a[(i, k)], V[i])
    objective.SetMaximization()

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        placements = []
        total_value = 0

        for i in range(T):
            for k in range(N[i]):
                if a[(i, k)].solution_value() > 0.5:
                    x_val = x[(i, k)].solution_value()
                    y_val = y[(i, k)].solution_value()
                    r_val = r[(i, k)].solution_value()
                    rotation_flag = 1 if r_val > 0.5 else 0

                    placements.append([
                        i,
                        round(x_val),
                        round(y_val),
                        rotation_flag
                    ])

                    total_value += V[i]

        print(json.dumps({"placements": placements, "total_value": total_value}))
    else:
        print(json.dumps({"placements": [], "total_value": 0}))

if __name__ == "__main__":
    solve_packing_problem()
